export function ArtemisAnnouncementBanners({ className, variant = "stacked-cards" }: ArtemisAnnouncementBannersProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }

"use client";
// @zeus-internal
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { AnnouncementCard } from "./04-stacked-cards/card";
export default function AnnouncementBannersStackedCards() {
    const reduced = Boolean(useReducedMotion());
    const [visible, setVisible] = useState(true);
    const [active, setActive] = useState(0);
    const [inView, setInView] = useState(true);
    const container = useRef<HTMLDivElement>(null);
    const [clientCards, setClientCards] = useState(false);
    useLayoutEffect(() => {
        if (reduced && container.current?.closest("[data-variant-index]"))
            setClientCards(true);
    }, [reduced]);
    useEffect(() => {
        const element = container.current;
        if (!element)
            return;
        const observer = new IntersectionObserver(([entry]) => setInView(entry.isIntersecting));
        observer.observe(element);
        return () => observer.disconnect();
    }, []);
    useEffect(() => {
        if (reduced || !visible || !inView)
            return;
        const timer = window.setInterval(() => setActive(current => (current + 1) % 3), 4600);
        return () => window.clearInterval(timer);
    }, [reduced, visible, inView]);
    return <div ref={container} className="art:w-full">
  {(!reduced || visible) && <AnimatePresence initial={false}>
  {visible && <motion.aside aria-label="Announcements" className="art:mx-auto art:w-full art:max-w-4xl art:overflow-hidden" initial={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: reduced ? 0 : 0.45, ease: ARTEMIS_EASE_OUT }}>
   <div className="art:relative art:h-[20rem] art:@min-[640px]/artemis:h-[15rem]">
   {[0, 1, 2].map(index => <AnnouncementCard key={`${clientCards ? "client" : "initial"}-${index}`} index={index} rank={(index - active + 3) % 3} reduced={reduced} onShow={() => setActive(index)} onPrevious={() => setActive(current => (current + 2) % 3)} onNext={() => setActive(current => (current + 1) % 3)} onDismiss={() => setVisible(false)}/>)}
   </div>
  </motion.aside>}
  </AnimatePresence>}
 </div>;
}

